#include <bits/stdc++.h>
using namespace std;

long long phi(long long n) {
    long long result = n;

    for (long long p = 2; p <= n / p; ++p) {
        if (n % p == 0) {
            while (n % p == 0)
                n /= p;
            result -= result / p;
        }
    }

    if (n > 1)
        result -= result / n;

    return result;
}

int main() {
    long long n, k;
    scanf("%lld %lld", &n, &k);

    k = (k + 1) / 2;
    long long result = n;

    while (k--) {
        result = phi(result);
    }

    printf("%lld", result % 1000000007LL);
    return 0;
}

